WA='https://wa.me/6285746499697?text='
PAGES=[
 dict(slug='airbnb-management', title='Airbnb Management in Bali | BaliVillas',
  description='Airbnb management for Bali villas: listing optimisation, dynamic pricing, guest messaging 24/7, cleaning, maintenance, owner reports. 20% commission, no fixed fees.',
  h1='Airbnb management <span class="it">in Bali</span>', kicker='Airbnb management · Bali', related=['holiday-rental-management','airbnb-co-hosting','villa-marketing-and-listings','dynamic-pricing-and-revenue-management','pricing'],
  lead='We run your Airbnb listing as a business: photos, copy, pricing, calendar, every guest message and every changeover, then a monthly report with the payout. You keep the villa and the decisions; we do the daily work across Sanur, Canggu, Umalas, the Bukit and the rest of south Bali.',
  sections=[
   ('What Airbnb management includes',['Everything between a guest typing "villa in Bali" and the money landing in your account:',
     '* Listing build or rebuild: photo shoot, photo order, title and description, amenities, house rules, instant-book settings.',
     '* Pricing: seasonal base rates, event and last-minute rules, minimum stays, gap-night logic, reviewed weekly.',
     '* Guest messaging 24/7 in English, from enquiry to review reply, with response times that keep the listing visible.',
     '* Check-in and check-out, cleaning turnover, linen and amenities, inspections with photos.',
     '* Maintenance rounds and repairs with pre-approved budgets.',
     '* Monthly owner statement: every booking, Airbnb fees, our 20% commission, expenses with receipts, net payout.',
     'Airbnb is one channel. The same villa is also listed on Booking.com, Agoda and our own direct-booking site with one synced calendar, so you are not dependent on a single platform.']),
   ('How we grow an Airbnb listing in Bali',['A Bali listing competes with thousands of others. What moves it is not a trick but a set of disciplines: a first photo that shows the pool and the villa in one frame; a title that says what the villa is, not how it feels; a description written for the guest who is comparing ten tabs; amenities ticked honestly; minimum stays that match the season; a reply within minutes; and every review answered.',
     'We review each listing monthly against its search position and its conversion, and we change one thing at a time so we know what worked. Owners see the listing as guests see it, plus the numbers behind it.']),
   ('Airbnb rules in Bali owners ask about',['Renting a villa nightly in Bali needs the right licence for the property, a tax registration and a working relationship with the local banjar. What exactly applies depends on the ownership structure and the zoning of the land, and it changes; we check the status of every villa before the first booking and point you to a licensed consultant where paperwork is missing. We are not a law firm and we do not give legal advice; we make sure the villa is not rented blind. Our owner guides on licences and short-term rental rules explain the background.']),
   ('Airbnb management by area',['We manage villas in Sanur, Renon, Canggu, Pererenan and Berawa, Umalas and Kerobokan, Ungasan, Uluwatu and Jimbaran. Each area has its own page with the local specifics: who books there, which streets rent, how we run housekeeping and maintenance on the ground.']),
   ('Co-hosting or full management?',['If you want to keep your own Airbnb account and payouts, we can join as a co-host and run the operations on your listing. Full management means we run the villa on all channels under one agreement. The co-hosting page explains the difference in access, liability and fees.']),
  ],
  faq=[('How much does it cost to have someone manage an Airbnb in Bali?','With us: 20% of actual booking revenue, nothing fixed. Cleaning consumables, repairs and utilities are billed at cost with receipts and shown in your monthly report.'),
       ('Can I keep my listing and its reviews?','Where Airbnb allows it, yes. We take over an existing listing rather than starting from zero, and future bookings already in the calendar are honoured.'),
       ('Who replies to guests?','Our team in Bali, 24/7. Owners are not in the guest chat unless they want to be.'),
       ('What about Booking.com and other sites?','Included. One calendar synced across Airbnb, Booking.com, Agoda and our direct site.')]),
 dict(slug='holiday-rental-management', title='Holiday & Short-Term Rental Management Bali | BaliVillas',
  description='Short-term and holiday rental management for Bali villas on Airbnb, Booking.com, Agoda and direct: channel manager, dynamic pricing, guest care, housekeeping, reports.',
  h1='Holiday rental management <span class="it">in Bali</span>', kicker='Short-term rental management · Bali', related=['airbnb-management','long-term-rental-management','dynamic-pricing-and-revenue-management','housekeeping-and-cleaning','pricing'],
  lead='Nightly and weekly rentals earn the most per night and need the most work: daily messages, changeovers, pricing that follows demand and a house that is always ready. We run both sides, the sales and the house, for villas across south Bali on a single 20% commission.',
  sections=[
   ('Channels we sell your villa on',['Airbnb, Booking.com, Agoda and Expedia, plus our own site balivillas.ai where returning guests book direct without platform fees. One channel manager keeps every calendar in sync so a villa is never double-booked. Each villa also gets its own page and gallery on our site, which is where repeat guests and referrals land.']),
   ('Pricing that follows demand',['Seasonal base rates per villa, an event calendar (Nyepi, Galungan, Christmas, the Australian and European school holidays), minimum stays in high season, gap-night rules and last-minute logic. Rates are reviewed weekly. You can see the rate calendar and set a floor price below which we do not sell.']),
   ('Operations behind every stay',['* Cleaning turnover with a room-by-room checklist and photo check.','* Linen, towels and amenities stocked and replaced on a cycle.','* Welcome and check-in by a person, not a lockbox, unless you prefer self check-in.','* A 24/7 guest line for anything from a blown fuse to a late flight.','* Maintenance rounds and pool care on schedule, repairs with pre-approved budgets.','* Damage deposits collected where the channel allows it and claims handled by us.']),
   ('Licences and taxes for short-term lets',['A short-term rental in Bali needs the right licence for the property, a tax registration and guest reporting. We check the status before the first booking, help with the paperwork through licensed consultants and handle the ongoing guest reporting. Our guides on licences and short-term rental rules give the detail; we do not give legal advice.']),
   ('Nightly, weekly or monthly? Choosing the mix',['Not every villa should be rented nightly all year. For many homes the best plan is nightly rates in high season and monthly stays in the low months, with owner use blocked first. We run both under the same agreement; the long-term rental management page explains the monthly side.']),
  ],
  faq=[('Do you offer marketing only, without operations?','No. Marketing without control of the house produces bad reviews. We manage the whole stay or, on Airbnb, work as a co-host with access to the operations.'),
       ('Is there a minimum contract?','Terms are set out in a short agreement with clear exit conditions; ask for it on WhatsApp and you will have it the same day.'),
       ('How fast can you start?','After a visit and a signed agreement, most villas go live within about two weeks.')]),
 dict(slug='long-term-rental-management', title='Long-Term Villa Rental Management Bali | BaliVillas',
  description='Management for monthly and yearly villa rentals in Bali: tenant screening, contracts, deposits, rent collection, maintenance, owner reports. Sanur, Renon, Umalas, Canggu.',
  h1='Long-term rental management <span class="it">in Bali</span>', kicker='Monthly & yearly rentals · Bali', related=['sanur','renon-denpasar','umalas','holiday-rental-management','pricing'],
  lead='Monthly and yearly lets mean fewer turnovers, steadier cash and a tenant who treats the villa as a home. We find and screen the tenant, write the contract, hold the deposit, collect the rent and keep the house in shape, with the same monthly owner report as for short stays.',
  sections=[
   ('What long-term management includes',['* Listing on long-stay channels and our own site; viewings arranged and attended by us.','* Tenant screening: ID and visa status, references, purpose of stay.','* Contract in plain English, deposit held, inventory signed at move-in.','* Monthly rent collection and utility handling as agreed.','* Monthly inspections, maintenance and pool care on schedule.','* Exit inspection, deposit settlement, turnover to the next tenant or to nightly rentals.']),
   ('Where monthly rentals work best',['Sanur, Renon and Umalas have the strongest long-stay demand among the areas we cover: retirees, families on a school year, remote workers and professionals in Denpasar. Central Canggu is different: shorter stays and higher turnover, with monthly demand mainly in the low season. Each area page explains the local mix.']),
   ('Tenant screening and contracts',['A good tenant is found by asking the right questions before the viewing, not after the deposit. We check identity and visa status, ask for references and for the purpose of the stay, and we write house rules into the contract: guests, pets, noise, maintenance access. Deposits are held and returned against a signed inventory.']),
   ('Fees for long-term lets',['Our commission is 20% of the rent actually collected, nothing fixed, the same as for nightly rentals. Utilities and repairs are passed through at cost with receipts. For yearly contracts paid up front, the commission is settled per payment as it arrives.']),
   ('Mixing long and short lets',['Many owners do both: a monthly tenant from February to May, nightly guests in the peak months, and their own stay in between. We plan the year around your dates first, then price the rest.']),
  ],
  faq=[('Can tenants pay in a foreign currency?','Rent is usually collected in IDR; other arrangements are set out in the contract case by case.'),
       ('Who pays utilities?','Set in the contract: typically the tenant for electricity and internet, with readings taken at move-in and move-out by us.'),
       ('What notice periods do you use?','Written into each contract and explained to you before signing; we recommend terms that keep the calendar flexible for high season.')]),
 dict(slug='luxury-villa-management', title='Luxury Villa Management in Bali | BaliVillas',
  description='Management for luxury and large villas in Bali: bespoke guest experience, vetted staff, concierge, revenue management, transparent reporting. We run a 6BR and a 9BR villa.',
  h1='Luxury villa management <span class="it">in Bali</span>', kicker='Premium & large villas · Bali', related=['guest-services-and-concierge','villa-staff-management','dynamic-pricing-and-revenue-management','pererenan-berawa','pricing'],
  lead='A premium villa needs a different operating standard, not just a higher price. We run Villa The Wave, a six-bedroom beachside house in Canggu, and Leonardo, a nine-bedroom resort villa in Pererenan, and we bring that standard to other high-value homes: vetted guests, trained staff, concierge and reporting an owner can read like an asset statement.',
  sections=[
   ('What luxury management means in practice',['* Guest vetting before confirmation for large groups and events.','* Arrival by a named host, in-villa briefing, a WhatsApp line answered by a person around the clock.','* Staff ratios that fit the house: housekeeping, pool and garden, a cook or butler where the villa has one.','* Concierge: chefs, drivers, transfers, spa, tours, celebrations.','* Maintenance standards for timber, pools, generators and finishes that a premium guest notices.','* Discretion: no owner names, no addresses in listings, NDAs on request.']),
   ('Our premium villas',['Villa The Wave sleeps twelve across six bedrooms a short walk from the beach in Canggu; Leonardo sleeps eighteen across nine bedrooms in Pererenan and is run with its own staff team. Both are on this site with photos and guest reviews, and both are the reference for how we run large houses.']),
   ('Revenue management for high-rate villas',['Large villas sell fewer, longer bookings: families, retreats, corporate groups and celebrations. We price per season and per group size, use minimum stays and deposits, work with agents and repeat guests, and protect the rate rather than chasing occupancy with discounts.']),
   ('Staff and household management',['Premium villas usually come with a team. We assess, keep or rebuild it, handle contracts and payroll, train to a written standard and supervise daily. Your staff costs appear in the monthly report next to the revenue they support.']),
  ],
  faq=[('Is there a minimum villa size?','No. Luxury is about standard, not bedrooms; a two-bedroom cliff villa can run on the same model as a nine-bedroom estate.'),
       ('Can I use the villa myself?','Yes. Owner dates are blocked first and the house is prepared for you as for a guest.'),
       ('Is the commission the same?','Yes: 20% of actual revenue, with staff, consumables and repairs at cost in the report.')]),
 dict(slug='airbnb-co-hosting', title='Airbnb Co-Host in Bali for Villa Owners | BaliVillas',
  description='Local Airbnb co-hosting in Bali: we run messaging, check-ins, cleaning and pricing on your own listing; you keep the account and payouts. Sanur, Canggu, Umalas, Bukit.',
  h1='Airbnb co-hosting <span class="it">in Bali</span>', kicker='Co-host · Bali', related=['airbnb-management','pricing','housekeeping-and-cleaning','sanur','canggu'],
  lead='Some owners want to keep the Airbnb account, the payouts and the reviews in their own name and simply need a reliable team on the ground. That is co-hosting: you add us as a co-host on your listing and we run the operations. Here is what it involves and when full management is the better choice.',
  sections=[
   ('What a Bali co-host actually does',['* Answers every guest message, 24/7, in English.','* Runs check-in and check-out and the cleaning turnover.','* Coordinates maintenance and pool care and reports issues with photos.','* Proposes pricing and calendar rules; you approve them.','* Replies to reviews and handles guest problems on the spot.']),
   ('Co-host vs full management',['As a co-host we work inside your Airbnb account: you receive the payouts, you own the listing and you sign the platform terms. Under full management we run the villa on every channel, collect payments, pay expenses and send you one monthly statement and one payout. Co-hosting suits owners who already run a listing well and need hands in Bali; full management suits owners who want to stop thinking about it.']),
   ('How much a co-host costs in Bali',['Our co-hosting fee is 20% of the booking revenue on the stays we run, invoiced monthly against the Airbnb statement. Cleaning consumables and repairs are billed at cost with receipts. There is no fixed monthly fee.']),
   ('Areas we co-host in',['Sanur, Renon, Canggu, Pererenan and Berawa, Umalas, Ungasan, Uluwatu and Jimbaran, wherever our housekeeping and maintenance rounds already run.']),
  ],
  faq=[('How do I add you as a co-host on Airbnb?','From your listing settings you invite a co-host by email; we tell you which permissions we need for messaging, calendar and pricing.'),
       ('Can you co-host on Booking.com too?','Booking.com has no co-host role; for multi-channel villas we recommend full management with one synced calendar.'),
       ('Can we switch to full management later?','Yes, at any time; the same team continues and the listing is moved into our channel manager.')]),
 dict(slug='villa-marketing-and-listings', title='Villa Marketing in Bali: Photos, Listings, Direct | BaliVillas',
  description='Villa marketing in Bali as part of management: professional photos, listing copy on every channel, a direct-booking page, repeat-guest email and Google profile.',
  h1='Villa marketing <span class="it">and listings</span>', kicker='Marketing · Bali', related=['dynamic-pricing-and-revenue-management','holiday-rental-management','airbnb-management','pricing'],
  lead='Most self-managed villas lose bookings before the guest ever sees the house: dark photos, a listing written for the owner, no direct site and no reason to come back. Marketing is included in our management, and this is exactly what we do.',
  sections=[
   ('Photos and listing copy',['A shoot at the right time of day, a first photo that shows pool and villa together, rooms in the order a guest walks through them, captions that name what they see. Copy is written for the comparison tab: what the villa is, who it suits, what is within walking distance, what it is not. Amenities are ticked honestly, because a wrong tick becomes a bad review.']),
   ('Where your villa is shown',['Airbnb, Booking.com, Agoda and Expedia through one channel manager, plus a dedicated page and photo gallery on balivillas.ai and the area catalogue it belongs to. Our own pages rank for the areas we work in and bring direct bookings without platform commission.']),
   ('Direct bookings and repeat guests',['Every guest who stays with us is invited to book direct next time. We keep a guest list per villa, send seasonal availability by email and WhatsApp, and price direct bookings so that the guest saves the platform fee and you keep more of the rate.']),
   ('Reviews as marketing',['A review is the most read paragraph on any listing. We ask for it at the right moment, answer every one, and deal with problems during the stay so they do not end up in the text. When a bad review happens, we reply factually and fix the cause; our owner guides explain how we handle it.']),
   ('Marketing-only or full management?',['We do not sell marketing as a stand-alone service. Photos and listings without control of pricing, guests and the house produce bookings that disappoint, and disappointed guests write the reviews. Marketing is part of the 20% commission, not an extra line.']),
  ],
  faq=[('Do you use my existing photos?','If they are good, yes. Usually we reshoot at least the hero images.'),('Can I see the listings before they go live?','Yes. You approve copy and photos, and you can ask for changes at any time.'),('Do you run Instagram for my villa?','Our own channels feature the villas we manage; individual villa accounts are not part of the service.')]),
 dict(slug='dynamic-pricing-and-revenue-management', title='Villa Revenue Management & Dynamic Pricing Bali | BaliVillas',
  description='Revenue management for Bali villas: seasonal base rates, event and last-minute pricing, minimum stays, gap nights and owner-visible reports. Part of our management.',
  h1='Dynamic pricing and <span class="it">revenue management</span>', kicker='Pricing · Bali', related=['holiday-rental-management','villa-marketing-and-listings','long-term-rental-management','income-calculator'],
  lead='Pricing is the lever that moves income fastest and the one most villas pull wrong: one rate all year, or discounts until the calendar fills with the cheapest guests. Here is how we set rates for the villas we manage and how you can see every change.',
  sections=[
   ('How we set your rates',['Each villa gets a seasonal base rate built from its own history and from the villas we run in the same area. On top of that: an event calendar (Nyepi, Galungan, Christmas and New Year, the Australian and European school holidays), minimum stays that rise in high season, gap-night rules that fill short holes without cutting the rate for long stays, and last-minute logic for the final days. Rates are reviewed weekly and changed with a reason.']),
   ('Occupancy versus rate: what we optimise',['A full calendar at half price is not a result. We track revenue per available night and adjust rate and minimum stay together. Sometimes the right move is to hold the rate and accept an empty week; sometimes it is to open a two-night gap. Owners see both the calendar and the reasoning in the monthly report.']),
   ('Low season strategy',['Between February and May and in October and November demand thins across Bali. Instead of discounting nightly rates to the floor, we switch part of the calendar to monthly stays, raise minimum stays for the remaining nightly weeks and use the time for maintenance. Owner use is planned into the same low season where possible.']),
   ('What you can control',['A floor price we never go below, owner dates, house rules that affect which guests we accept, and any decision on events or long-term tenants. Everything else is reported, not hidden.']),
  ],
  faq=[('Can I set a floor price?','Yes, per villa and per season if you like.'),('How often do rates change?','Reviewed weekly; changed when demand or the calendar changes, with the reason noted.'),('Can I see the rate calendar?','Yes. You get read access and a summary in the monthly report.')]),
 dict(slug='guest-services-and-concierge', title='Villa Concierge & Guest Services Bali | BaliVillas',
  description='Guest services and concierge for managed villas in Bali: 24/7 guest line, transfers, chefs, drivers, tours and in-villa services, so owners never take a guest call.',
  h1='Guest services and <span class="it">villa concierge</span>', kicker='Guest care · Bali', related=['housekeeping-and-cleaning','villa-staff-management','luxury-villa-management','your-villa-manager'],
  lead='Good guest care is what turns one booking into a five-star review and a repeat stay, and it is the part of villa ownership that ruins evenings. For the villas we manage, every guest has a person to write to, around the clock, and owners never take the call.',
  sections=[
   ('24/7 guest line and arrival',['Every booking gets a WhatsApp contact before arrival. Airport pickup can be arranged, the villa is opened by a host who walks the guest through the house, and questions from the first night onwards go to our line, staffed in Bali day and night. Late flights, a lost key, a fuse at midnight: handled by us.']),
   ('In-villa services and partners',['Private chefs, massage and spa at the villa, drivers and day tours, surf lessons, celebrations and flowers, laundry and babysitting through partners we have used for our own villas. Guests pay the partner; where a partner pays us a referral fee it is shown in your report.']),
   ('Handling issues and complaints',['Problems during a stay are fixed during the stay, not argued about in a review. The team is authorised to act within a set budget, the owner is informed of anything above it, and compensation follows a policy agreed with you in advance.']),
   ('How guest care protects your reviews',['Reviews are asked for at the right moment and answered every time. The average rating of our villas is shown on each villa page with the review count, straight from our booking system, so guests and owners see the same numbers.']),
  ],
  faq=[('Do guests pay extra for concierge?','Services are paid to the provider at their price; the concierge itself is part of management.'),('Is the guest line really 24/7?','Yes, staffed by our team in Bali.'),('Can I set rules for what guests may book?','Yes: events, extra guests, pets and noise are written into the house rules.')]),
 dict(slug='owner-reporting-and-payouts', title='Villa Owner Reports & Payouts in Bali | BaliVillas',
  description='How owners get paid at BaliVillas: a monthly statement with every booking, expense and fee, the payout schedule, tax notes and what to expect month by month.',
  h1='Owner reporting <span class="it">and payouts</span>', kicker='Transparency · Bali', related=['pricing','maintenance-and-pool-care','foreign-and-overseas-owners','your-villa-manager'],
  lead='You should never wonder where the money is. Every owner gets one statement a month that lists every booking, every expense with its receipt, our 20% commission and the net payout. Here is what it contains and when it arrives.',
  sections=[
   ('What is in the monthly statement',['* Every booking: dates, channel, guest count, gross amount and the platform fee taken by Airbnb or Booking.com.','* Direct bookings shown separately so you can see what the direct site earns.','* Our commission: 20% of actual revenue, one line.','* Expenses: cleaning consumables, laundry, repairs, utilities and licences, each with a receipt and a note on who approved it.','* Net payout and the date it was sent.','* Occupancy and average nightly rate for the month, compared with the same month a year earlier once we have it.']),
   ('When and how you are paid',['Statements are issued monthly after the month closes, and the net amount is transferred to the account you name, in Indonesia or abroad. Bank charges for international transfers are shown as a line, not hidden in the rate.']),
   ('Expenses: what we pay and what we ask first',['Routine consumables and small repairs run within a monthly budget you set. Anything above it is quoted, photographed and approved by you before the work starts. Receipts are attached to the statement; there is no markup on repairs.']),
   ('Taxes and the report',['The statement gives your accountant what they need: gross revenue by channel, fees, expenses and net. We do not give tax advice; our owner guides on rental income tax and tax registration explain the background and we can introduce a licensed accountant.']),
  ],
  faq=[('Can I see bookings in real time?','Yes, you get read access to the calendar; the statement is the monthly summary.'),('Do you hold a maintenance fund?','If you prefer, a small float is held for emergencies and shown in every statement.'),('What if a guest damages something?','Deposits and platform claims are handled by us and the outcome appears in the statement.')]),
 dict(slug='housekeeping-and-cleaning', title='Villa Housekeeping & Cleaning in Bali | BaliVillas',
  description='Housekeeping for villas under our management: turnover cleaning standards, linen and amenities, inspections, laundry, deep cleans and what each stay costs the owner.',
  h1='Villa housekeeping <span class="it">and cleaning</span>', kicker='Housekeeping · Bali', related=['maintenance-and-pool-care','villa-staff-management','guest-services-and-concierge','pricing'],
  lead='Clean villas get the reviews. Housekeeping is part of our management, not a separate cleaning service: our team cleans between every stay to a written checklist, a supervisor checks with photos, and linen and amenities are stocked on a cycle. This page explains the standard and what it costs you.',
  sections=[
   ('Turnover cleaning checklist',['Bedrooms stripped and remade with fresh linen; bathrooms descaled, not wiped; kitchen emptied of leftovers and cleaned inside the fridge and oven; floors washed; terraces and outdoor furniture cleaned; pool skimmed and checked; bins, bulbs, batteries and remotes tested; a photo of every room before the guest arrives. Time depends on the villa: a two-bedroom townhouse and a nine-bedroom estate do not get the same crew.']),
   ('Linen, towels and amenities',['Each villa carries enough sets to turn around a same-day changeover. Laundry runs on a cycle with a partner laundry or in-house where the villa has the machines. Amenities are stocked to a list agreed with you; replacements appear in the statement at cost.']),
   ('Deep cleans and pest control',['A deep clean is scheduled in the low season or after long stays; pest control and mattress cleaning are on a calendar rather than a complaint. Both are quoted and approved in advance.']),
   ('Who cleans: our team or your staff',['If you already employ housekeeping staff, we assess them, train them to the checklist and supervise; if not, our team covers the villa. Staff costs and our supervision are shown in the report either way.']),
   ('What cleaning costs the owner',['Guests pay a cleaning fee on nightly bookings where the channel allows it, and that fee offsets the turnover cost. Consumables and laundry are passed through at cost. There is no separate housekeeping fee on top of the 20% commission.']),
  ],
  faq=[('Do you offer one-off cleaning?','No; housekeeping is part of managing the villa.'),('Who checks the cleaning?','A supervisor, with photos per room before every arrival.'),('What about mid-stay cleaning?','Included on a schedule agreed for the villa; extra cleans can be booked by the guest.')]),
 dict(slug='maintenance-and-pool-care', title='Villa Maintenance & Pool Care in Bali | BaliVillas',
  description='Preventive maintenance for managed villas in Bali: weekly pool care, garden, AC servicing, plumbing, wet-season checks, repair approvals and cost reporting to the owner.',
  h1='Villa maintenance <span class="it">and pool care</span>', kicker='Maintenance · Bali', related=['housekeeping-and-cleaning','owner-reporting-and-payouts','ungasan','pricing'],
  lead='A villa in the tropics decays fast when nobody is looking: salt, humidity, sun, rain and a pool that turns green in a week. Preventive care is cheaper than emergency repair. This is the routine we run for the villas we manage and how you approve every rupiah spent.',
  sections=[
   ('Weekly and monthly routine',['* Pool: chemistry checked and balanced, skimmed and brushed, pump and filter inspected, weekly.','* Garden: watering, trimming, pest control, weekly.','* Air-conditioning: filters cleaned monthly, full service on a schedule.','* Water, pumps and tanks: checked monthly, more often on the Bukit.','* Electrics, gas, safety equipment: inspected monthly with a checklist.','* Roof, gutters and drains: cleared before the rainy season.']),
   ('Pool care',['Most bad reviews about pools are about chemistry and cloudy water, not about tiles. Our pool round tests and corrects the water, checks the pump hours and the filter pressure and logs it, so a problem is caught before a guest photographs it.']),
   ('Repairs: approval and pricing',['Small repairs are done within the monthly budget you set. Anything above it is photographed, quoted by our vendors and approved by you before work starts. The invoice goes into your statement at cost; we do not mark up repairs.']),
   ('Wet season and long vacancy checks',['Before the rains: roof, gutters, drains, generator, outdoor timber. During long vacancies or owner absences: a weekly walk-through with photos so the house is not discovered damp two months later.']),
   ('Inventory and asset register',['Every villa gets an inventory with photos at handover: furniture, appliances, linen counts, keys. It is the basis for deposit claims and for the replacement cycle we plan with you.']),
  ],
  faq=[('Do you offer pool maintenance alone?','No; pool care is part of managing the villa.'),('Who are your vendors?','Electricians, plumbers, AC technicians and pool suppliers we use for our own villas; quotes are shown to you.'),('What is the approval threshold?','Set with you at the start; typical is a small monthly float for routine items and approval for anything above it.')]),
 dict(slug='villa-staff-management', title='Villa Staff Management in Bali | BaliVillas',
  description='Staff management for villas in Bali: hiring and vetting, contracts, BPJS and payroll, training, rosters and cover, supervision, so the owner is never the employer of last resort.',
  h1='Villa staff <span class="it">management</span>', kicker='Staff · Bali', related=['housekeeping-and-cleaning','luxury-villa-management','owner-reporting-and-payouts','your-villa-manager'],
  lead='Staff are the villa: the guest remembers the person who opened the door, and the owner remembers the month nobody showed up. We hire, contract, pay, train and supervise villa staff so that you are not managing rosters from another time zone.',
  sections=[
   ('Keeping or replacing your existing staff',['Most villas come with people who have been there for years. We start by working with them: a written standard, a trial period under our supervision, and an honest conversation with you if it does not work. Replacing good staff is a loss; replacing bad staff late is a bigger one.']),
   ('Hiring and vetting',['Roles are defined in writing, candidates come through references from villas we already run, and every hire starts with a trial. Housekeeping, pool and garden, security and, where the villa has one, cook or butler.']),
   ('Contracts, BPJS and payroll',['Staff are employed under written contracts with the statutory social security registrations and paid monthly with payslips. Who the legal employer is depends on your ownership structure; we set it up with a licensed consultant and show the monthly cost as a line in your statement.']),
   ('Training and standards',['A cleaning checklist, a guest etiquette guide, safety rules around pools and electrics, and a WhatsApp reporting routine. Training is repeated when the standard slips, and the supervisor checks daily.']),
   ('Rosters, cover and holidays',['Galungan, Nyepi and the ceremonial calendar empty villas of staff if nobody plans for it. We roster cover across the villas we manage so a guest never arrives to a closed gate.']),
  ],
  faq=[('Do I keep my current staff?','If they meet the standard after a trial, yes; we prefer it.'),('Who is the employer?','Set up per villa with a licensed consultant; the cost is shown in your statement either way.'),('What if a staff member leaves?','Cover from our pool while we recruit; the guest never notices.')]),
 dict(slug='your-villa-manager', title='Your Villa Manager in Bali | BaliVillas',
  description='Who actually runs your villa at BaliVillas: a named villa manager, housekeeping and maintenance team, guest desk and finance, with response times and contacts.',
  h1='Your villa manager and <span class="it">local team</span>', kicker='The team · Bali', related=['guest-services-and-concierge','owner-reporting-and-payouts','housekeeping-and-cleaning','maintenance-and-pool-care'],
  lead='A person, not a hotline. Every villa we manage has a named villa manager who owns the calendar, the guests and the house, and behind them a housekeeping team, a maintenance round, a guest desk and finance. This page is about who does what and how you reach them.',
  sections=[
   ('Your named villa manager',['One manager is responsible for your villa: pricing decisions, guest problems, staff, repairs and the monthly statement. You have their WhatsApp. They visit the villa every week and know the pool pump by its noise.']),
   ('The team behind the manager',['Housekeeping crews per area; a maintenance and pool round that covers Sanur and Renon from our Sanur base, Canggu, Pererenan and Umalas from the west, and the Bukit from Ungasan; a guest desk that answers around the clock; and finance, which prepares statements and payouts.']),
   ('Response times and escalation',['Guest messages are answered around the clock. Owner messages are answered during Bali working hours, usually within the same day, and urgent matters at any time. Anything that costs money above your monthly budget is escalated to you before it is spent.']),
   ('How we communicate with owners',['A WhatsApp thread per villa, a monthly statement with a short written summary, and a call whenever you want one. Owners living abroad get photos and video walk-throughs on request; see the page for overseas owners.']),
  ],
  faq=[('Can I meet the manager before signing?','Yes; the first villa visit is done by the manager who would run it.'),('How many villas does one manager run?','Enough to know each one; we add managers as we add villas rather than stretching one across an island.'),('Do you have jobs available?','This page is about our service to owners; vacancies are not listed here.')]),
 dict(slug='pricing', title='Villa Management Fees in Bali: 20% Commission | BaliVillas',
  description='What villa management costs at BaliVillas: 20% of actual booking revenue, no fixed fee, what is included, what is billed at cost, and how the numbers work in a month.',
  h1='Villa management fees: <span class="it">20%, nothing fixed</span>', kicker='Pricing · BaliVillas', related=['income-calculator','owner-reporting-and-payouts','maintenance-and-pool-care','switch-to-the-host-bali'],
  lead='One number: we charge 20% of the revenue your villa actually earns. No fixed monthly fee, no onboarding fee, no markup on repairs, nothing when the villa does not earn. This page lists what the 20% covers, what is passed through at cost, and what we do not do.',
  sections=[
   ('Our fee model',['* 20% commission on actual booking revenue, nightly and monthly alike.','* No fixed monthly fee and no minimum charge in a slow month.','* No onboarding or exit fee.','* Platform fees charged by Airbnb, Booking.com and others are shown separately; they are not ours.','* Repairs, consumables and utilities are billed at cost with receipts, no markup.']),
   ('What is included in the 20%',['Marketing and listings on every channel and our own site; pricing and revenue management; guest messaging and the 24/7 guest line; check-in and check-out; housekeeping supervision and the turnover crew; maintenance rounds and pool care scheduling; staff supervision; licence and compliance checks; the monthly owner statement and payouts. The service pages describe each part.']),
   ('What is billed at cost',['Cleaning consumables and laundry; repairs and spare parts; utilities where they are not paid by the guest or tenant; licence and permit fees; staff salaries and their statutory contributions; international bank charges. Every item comes with a receipt in the statement, and anything above your monthly budget is approved by you first.']),
   ('How a month works',['Take any month: the villa earns a gross amount across channels. The platforms deduct their fees. From the net booking revenue we take 20%. Expenses for the month are listed with receipts. What remains is transferred to you with the statement. If a month earns nothing, we earn nothing.']),
   ('Commission, fixed fee or hybrid',['Managers in Bali charge in three ways: a percentage of revenue, a fixed monthly fee, or a low percentage plus fixed charges. A fixed fee is paid whether guests come or not; a hybrid hides the real cost across several lines. We chose a single commission because it is the only model where a slow month costs us too, and because one line is easier to check than five. Our owner guides compare the models in detail.']),
   ('Contract terms in plain words',['A short agreement: the villa, the scope, the 20%, how expenses are approved, owner dates, how either side ends the agreement. No exclusivity traps and no penalty for leaving if we do not deliver. Ask for the template on WhatsApp and you will have it the same day.']),
  ],
  faq=[('Is 20% negotiable?','It is the same for every villa; what varies is the scope, which is agreed at the visit.'),('Do you charge for the first visit and assessment?','No.'),('What about long-term contracts paid up front?','20% of each payment as it is received; nothing else.'),('Are there hidden costs?','No. Every rupiah that leaves the villa account is in the statement with a receipt.')]),
 dict(slug='foreign-and-overseas-owners', title='Villa Management for Foreign Owners Living Abroad | BaliVillas',
  description='Villa management in Bali for foreign owners living overseas: eyes on the ground, monthly reports, payouts abroad, licence and tax support, video inspections, an English-speaking team.',
  h1='Villa management for <span class="it">overseas owners</span>', kicker='Foreign & absent owners · Bali', related=['owner-reporting-and-payouts','licensing-and-compliance-help','your-villa-manager','switch-to-the-host-bali','income-calculator'],
  lead='You are in Melbourne, Milan or Amsterdam and the villa is in Sanur. Most of the owners we work with live abroad, and the service is built for it: a team you can reach, a report you can read, payouts where you are, and paperwork that does not wait for your next trip.',
  sections=[
   ('What absent owners get from us',['* A monthly statement with every booking, expense and receipt, and the payout sent abroad.','* Photo and video walk-throughs of the villa on request and after any repair.','* One WhatsApp thread with your villa manager; calls scheduled in your time zone.','* Repairs approved by you with photos and quotes before money is spent.','* Owner dates blocked first, and the villa prepared for your own stay.']),
   ('Languages and time zones',['The team works in English. Our owners are Australian, European, Singaporean and Indonesian, and the statement, the agreement and the messages are written so that they can be forwarded to your accountant or lawyer at home without translation.']),
   ('Licences, tax and paperwork help',['A foreign-owned villa rents legally only with the right licence for the property, a tax registration and guest reporting. We check what exists, tell you what is missing, and arrange it through licensed consultants who work with foreign owners. We do not give legal advice; we make sure the villa is not rented blind.']),
   ('Using your own villa',['Block your dates a season ahead and the calendar is priced around them. The villa is cleaned and stocked for you as for a guest, and staff are briefed that you are coming.']),
   ('Owner references',['We do not publish owner names without consent. Owners who are happy to talk to a prospective owner are introduced on request; ask your villa manager. Guest reviews of the villas we manage are shown on every villa page and below, straight from our booking system.']),
  ],
  faq=[('Can you pay me outside Indonesia?','Yes; transfers go to the account you name, with bank charges shown as a line.'),('How do I know the villa is actually maintained?','Weekly rounds are logged, and you get photos and videos on request and after any repair.'),('Can I visit unannounced?','It is your villa. Tell us when you land and the house will be ready.')]),
 dict(slug='new-villa-launch', title='New Villa Handover & Launch Management Bali | BaliVillas',
  description='From handover to first guest: snagging, furnishing checklist, licences, photos, listings, pricing and staff, so a newly built or bought Bali villa earns within weeks.',
  h1='Launching a <span class="it">new villa</span>', kicker='New build & handover · Bali', related=['licensing-and-compliance-help','villa-marketing-and-listings','dynamic-pricing-and-revenue-management','villa-staff-management','income-calculator'],
  lead='A new villa has no reviews, no history and usually a list of things the developer forgot. The launch plan is what earns the first months. Here is how we take a villa from handover to its first guest.',
  sections=[
   ('Launch plan and timeline',['Week one: handover walk-through, snagging list, inventory with photos, licence and tax check. Week two: furnishing gaps closed, staff briefed or hired, photo shoot. Weeks two to three: listings built on every channel and on our site, pricing set for a launch with no reviews, calendar opened. Most villas go live within about two weeks once the house is guest-ready; a villa that arrives without beds takes longer, and we say so at the first visit.']),
   ('Snagging and furnishing checklist',['Developers hand over houses, not rentals. The usual gaps: no blackout curtains, one set of linen, no bins, no first-aid kit, a kitchen with two pans, an internet line that was never ordered, a pool without a cover or a fence. We walk the villa with a rental checklist and give you a costed list before the shoot.']),
   ('Licences before the first booking',['A new villa needs its own licence and tax registration before it is advertised. We check the ownership and zoning documents, list what is missing and arrange it through licensed consultants. Advertising a villa without them is how owners meet the authorities for the first time.']),
   ('Photos, listings and launch pricing',['A villa with zero reviews needs a launch price that wins the first bookings from guests who will write the first reviews, then a steady climb to its real rate. We plan that curve in advance and review it weekly.']),
   ('Staff for a new villa',['Housekeeping, pool and garden are covered by our area team from day one; dedicated staff are hired if the villa size needs them, with contracts and payroll handled by us.']),
  ],
  faq=[('Can you start before construction is finished?','Yes; the earlier we see the plans, the fewer rental mistakes get built in.'),('Do you help with furniture buying?','We give the checklist and the priorities; buying is done by you or a designer, with our input on what guests need.'),('What does the launch cost?','Nothing beyond the 20% once bookings start; licence fees and furnishing are at cost.')]),
 dict(slug='switch-to-the-host-bali', title='Switch Villa Management Company in Bali | BaliVillas',
  description='Unhappy with your villa manager? How we take over a Bali villa: notice, listings and reviews transfer, staff, keys and calendar without cancelled bookings.',
  h1='Switching villa management <span class="it">without downtime</span>', kicker='Changing manager · Bali', related=['pricing','airbnb-management','villa-staff-management','owner-reporting-and-payouts','foreign-and-overseas-owners'],
  lead='Switching manager should not cost you a single booking, a single review or a good member of staff. This is the handover we run when a villa comes to us from another company, and what to check in your current contract before you give notice.',
  sections=[
   ('Signs your villa is under-managed',['Statements that arrive late or not at all; repairs that appear on invoices without photos; a calendar with holes in high season; reviews that mention dirt, slow replies or a broken pool; a manager who is hard to reach. One of these is a bad month; three of them is a pattern.']),
   ('How the transfer works',['* We visit the villa and read your current agreement with you.','* You give notice according to its terms; we plan the handover date around bookings.','* Listings and calendars are transferred or rebuilt; future bookings are honoured, nothing is cancelled.','* Staff are met, assessed and kept where they meet the standard.','* Keys, inventory and access codes are handed over against a signed list.','* Your first statement from us arrives after the first full month.']),
   ('Keeping your listings and reviews',['If the Airbnb or Booking.com account is in your name, listings and reviews stay with you and we take over as manager or co-host. If the account belongs to the previous company, reviews usually cannot be moved; we rebuild the listings and win the first reviews fast. We tell you which case applies before you give notice.']),
   ('Existing bookings, staff and keys',['Guests who booked under the previous manager arrive to the same villa and a better welcome; we honour the rate they paid. Staff contracts are reviewed and either continued or reissued. Keys and codes are changed on handover day.']),
   ('What to check in your current contract',['Notice period; exit fees; exclusivity clauses; who owns the listings and the photos; how deposits held for future bookings are transferred; what happens to unpaid statements. Our guide on management contract clauses walks through each of them, and we will read yours with you.']),
  ],
  faq=[('Will guests notice the change?','Only that replies got faster.'),('Do you charge for the takeover?','No; the 20% applies to bookings from the handover date.'),('Can you take over mid-season?','Yes; the handover is planned around the calendar so no stay falls between two managers.')]),
 dict(slug='rent-out-my-villa', title='Rent Out Your Villa in Bali: We Do Everything | BaliVillas',
  description='Want to rent out your villa in Bali? We license, list, price, host and maintain it and send a monthly report. Nightly or monthly lets, 20% commission, no fixed fee.',
  h1='Rent out your villa <span class="it">in Bali</span>', kicker='First-time landlords · Bali', related=['holiday-rental-management','long-term-rental-management','pricing','income-calculator','licensing-and-compliance-help','new-villa-launch'],
  lead='You own the villa; we turn it into a rental. Licence check, photos, listings, pricing, guests, cleaning, maintenance and a monthly statement, on a 20% commission with nothing fixed. Here is what happens, what you decide and what it will cost and earn.',
  sections=[
   ('Nightly or monthly: which suits your villa',['Nightly rentals earn more per night and need daily operations; monthly rentals earn less per night, cost less to run and suit residential areas. Sanur, Umalas and Renon carry both; central Canggu leans nightly; the Bukit leans nightly with couples. After the visit we recommend a mix and a calendar, and you decide.']),
   ('What we do, what you decide',['We do: licence check, photo shoot, listings on every channel and our site, pricing, guest messaging 24/7, check-in, housekeeping, maintenance and pool care, staff, the monthly statement and the payout. You decide: your own dates, the floor price, house rules, whether to allow events or pets, the monthly repair budget and anything above it.']),
   ('Can a foreigner rent out a villa in Bali?',['Yes, when the property has the right licence for rental, the owner or the entity holding the property is registered for tax, and guests are reported as required. What applies depends on how the villa is held; we check the documents and arrange what is missing through licensed consultants. Our owner guide on renting out legally as a foreigner explains the options.']),
   ('What it will cost and earn',['Cost: 20% of actual revenue plus consumables, repairs and utilities at cost with receipts. Earnings depend on area, bedrooms, condition and season; use the income calculator with your own expected nightly rate for a first range, then ask us for an estimate after the visit.']),
   ('Timeline to first guest',['Visit and honest assessment; agreement; licence check; photos and listings; first guest, typically within about two weeks of a guest-ready villa. A villa that needs furnishing or paperwork takes longer, and we tell you how long at the visit.']),
  ],
  faq=[('Do I need to be in Bali?','No. Most of our owners live abroad; the agreement, the handover and the reports work remotely.'),('What if I only want to rent for part of the year?','Block your months first; we rent the rest.'),('Is there a fee to start?','No. Licence and permit fees are paid at cost if they are needed.')]),
 dict(slug='villa-investment-management', title='Villa Management for Investors in Bali | BaliVillas',
  description='For investors buying a Bali villa to let: pre-purchase income estimate, launch, management and reporting that reads like an asset report, plus resale support.',
  h1='Villa management <span class="it">for investors</span>', kicker='Buy-to-let · Bali', related=['income-calculator','new-villa-launch','holiday-rental-management','owner-reporting-and-payouts','pricing'],
  lead='You bought a yield; we run it like one. For investors we start before the purchase with an honest estimate on the specific villa, launch it, manage it and report the numbers an asset manager wants: occupancy, average rate, revenue per available night, expenses and net. When you sell, the booking history goes with the villa.',
  sections=[
   ('Before you buy: an estimate on a specific villa',['Send us the listing or the plans. We look at the area, the bedrooms, the access and the licence situation and give you a range based on the villas we run nearby, with the assumptions written down. If a villa will not rent, we say so before you sign; that has saved several buyers from the wrong street.']),
   ('KPIs we report',['Occupancy, average nightly rate, revenue per available night, direct-booking share, expenses by category, net payout and the yield on your purchase price once you give it to us. Monthly, in one statement, comparable month to month.']),
   ('Launch and management',['The new-villa launch page describes the path from handover to first guest; the holiday-rental page describes the operation. Both run on the same 20% commission with expenses at cost.']),
   ('Selling later',['A villa with two years of clean statements and reviews sells faster and better than an empty one. When the time comes, our villas-for-sale desk lists it with its rental history, and the new owner can keep the management in place.']),
  ],
  faq=[('Do you guarantee a yield?','No, and nobody honest does. We give a range with assumptions and report the real numbers every month.'),('Can you manage several villas as a portfolio?','Yes; one statement per villa and a portfolio summary.'),('Do you help with the purchase itself?','We give the rental view; legal and tax due diligence is done by licensed advisers we can introduce.')]),
 dict(slug='licensing-and-compliance-help', title='Villa Licence & Compliance Help in Bali | BaliVillas',
  description='How we help Bali villa owners with rental licences and compliance: pondok wisata and NIB checks, tax registration pointers, banjar relations, tourist levy, guest reporting.',
  h1='Licensing and <span class="it">compliance help</span>', kicker='Licences · Bali', related=['new-villa-launch','rent-out-my-villa','foreign-and-overseas-owners','pricing'],
  lead='We are not a law firm, but we make sure the paperwork exists before the first guest. Every villa we take on is checked for its rental licence, business registration, tax status and local obligations, and what is missing is arranged through licensed consultants.',
  sections=[
   ('What we check before launch',['* The rental licence that matches the property and its zoning.','* Business registration and the correct activity code where the villa is held by a company.','* Tax registration of the owner or the entity, and how rental income will be declared.','* The banjar: who to talk to, what the community expects, what fees apply.','* Insurance and safety basics a guest would expect.']),
   ('What we help with, what we do not',['We check, explain and arrange through licensed consultants who work with foreign owners; we file what a manager can file and we chase the rest. We do not give legal or tax advice and we do not sign documents on your behalf without a mandate.']),
   ('Ongoing compliance',['Guest registration and reporting as required locally, the tourist levy where it applies, banjar contributions, licence renewals on a calendar. All of it is shown in your statement.']),
   ('Costs',['Consultant and government fees are passed through at cost with receipts. Our own time is part of the 20% commission.']),
  ],
  faq=[('My villa is already rented without a licence; can you help?','Yes. We check what is missing and arrange it; until then we advise on what can and cannot be advertised.'),('Which licence do I need?','It depends on the property and how it is held; that is exactly what the check answers.'),('Do you handle tax filings?','No; a licensed accountant does, with the statements we provide.')]),
 dict(slug='owner-reviews-and-case-studies', title='BaliVillas Reviews: Guests and Owners',
  description='What guests say about villas managed by BaliVillas, straight from our booking system, with ratings and review counts per villa, and how to get an owner reference.',
  h1='Reviews of villas <span class="it">we manage</span>', kicker='Reviews · BaliVillas', related=['your-villa-manager','pricing','foreign-and-overseas-owners','income-calculator'],
  lead='Reviews you can check, not testimonials we wrote. The guest reviews below come straight from our booking system for the villas we manage, with the platform and the date; the average rating on each villa page is calculated over all reviews, not only the good ones. Owner references are given personally, on request.',
  sections=[
   ('How to read these reviews',['Each villa page on this site shows its rating, the number of reviews and the 5-star reviews with text, synced from Airbnb, Booking.com and direct bookings. Nothing is edited. A villa with three reviews is a villa that joined us recently; the count grows with each season.']),
   ('Owner references',['We do not publish owner names or testimonials without consent, and we do not invent them. Several owners are happy to speak with a prospective owner about how the management works in practice; ask your villa manager and we will introduce you.']),
   ('Where else to look',['Our villa pages and the area catalogues; the platforms where the villas are listed; and a visit to any of our villas in Sanur, Canggu, Umalas or Ungasan if you are in Bali.']),
  ],
  faq=[('Are the reviews real?','Yes. They are pulled from the booking system by an automated sync and shown with the channel and date; the average includes every review, good or bad.'),('Can I talk to an owner?','Yes, on request; we introduce you personally.'),('Where are the case studies with numbers?','We publish figures only with the owner\'s consent and a named villa; ask for a walk-through of a comparable villa\'s statements at the visit.')]),
]
